import{_ as a,a as t,o as i,a6 as n}from"./chunks/framework.CJDy2q7X.js";const l=JSON.parse('{"title":"Campaigns","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/communications/campaigns/index.md","filePath":"api/rest-api/admin/marketing/communications/campaigns/index.md","lastUpdated":1786429091000}'),s={name:"api/rest-api/admin/marketing/communications/campaigns/index.md"};function o(r,e,m,d,c,p){return i(),t("div",null,e[0]||(e[0]=[n('<h1 id="campaigns" tabindex="-1">Campaigns <a class="header-anchor" href="#campaigns" aria-label="Permalink to &quot;Campaigns&quot;">​</a></h1><p>A <strong>campaign</strong> pairs an email template with a customer group (and an optional event) and sends that template to the group. It mirrors the admin <strong>Marketing → Communications → Campaigns</strong> screen.</p><h2 id="how-a-campaign-works" tabindex="-1">How a campaign works <a class="header-anchor" href="#how-a-campaign-works" aria-label="Permalink to &quot;How a campaign works&quot;">​</a></h2><p>A campaign brings together four pieces and then sends them as one email blast.</p><ul><li><strong>Template</strong> — <code>marketing_template_id</code> points at the <a href="/api/rest-api/admin/marketing/communications/templates/">email template</a> whose HTML body is sent. The <code>subject</code> is the email subject line.</li><li><strong>Audience</strong> — <code>customer_group_id</code> selects which customer group receives the email. Only subscribed members of that group are mailed. When the group is the guest group, the guest newsletter subscribers are mailed instead.</li><li><strong>Channel</strong> — <code>channel_id</code> is the storefront channel the campaign sends from.</li><li><strong>Event</strong> — <code>marketing_event_id</code> is an optional <a href="/api/rest-api/admin/marketing/communications/events/">event</a> the campaign can be timed against; it may be <code>null</code>.</li></ul><p><strong>Status.</strong> <code>status</code> (<code>0</code>/<code>1</code>) toggles the campaign on. The <a href="/api/rest-api/admin/marketing/communications/campaigns-send.html">send</a> action refuses an inactive (<code>status = 0</code>) campaign.</p><p><strong>Resolved objects.</strong> The <a href="/api/rest-api/admin/marketing/communications/campaigns-detail.html">detail</a> endpoint resolves the <code>channel</code>, <code>customerGroup</code>, <code>marketingTemplate</code>, and <code>marketingEvent</code> objects (<code>marketingEvent</code> is an object or <code>null</code> when no event is linked). These objects are <code>null</code> on list rows.</p><p><strong>Sending.</strong> Send queues the email to every subscribed member of the customer group right away, skipping any event-date gate. There is no mass-delete for campaigns — the admin UI exposes per-row delete only.</p><p><strong>Relations.</strong> Campaigns draw their body from <a href="/api/rest-api/admin/marketing/communications/templates/">Email Templates</a>, can be timed against <a href="/api/rest-api/admin/marketing/communications/events/">Events</a>, and reach the subscribed members tracked under <a href="/api/rest-api/admin/marketing/communications/subscribers/">Newsletter Subscribers</a>.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns-list.html">List</a></td><td><code>GET /api/admin/marketing/campaigns</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/campaigns/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns-create.html">Create</a></td><td><code>POST /api/admin/marketing/campaigns</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns-update.html">Update</a></td><td><code>PUT /api/admin/marketing/campaigns/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/campaigns/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/campaigns-send.html">Send</a></td><td><code>POST /api/admin/marketing/campaigns/{id}/send</code></td></tr></tbody></table><p>All Campaigns endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',12)]))}const h=a(s,[["render",o]]);export{l as __pageData,h as default};
